using System;
using System.IO;
namespace PZ3D {
 static class LegacyPresentationBridgeTests {
  static void Check(bool v,string s){if(!v)throw new Exception("FAIL: "+s);Console.WriteLine("PASS: "+s);}
  public static void Run(){string source=Path.Combine(Engine.DetectGame(),"..","..","workshop","content","108600","3813032735");string originalJar=Path.Combine(source,"mods",ShootClient.Id,"42","media","java","client","ISeeThem.jar");if(!File.Exists(originalJar)){Console.WriteLine("SKIP: bridge lifecycle needs locally downloaded pinned author fixture; not embedded");return;}string root=Path.Combine(LauncherTestPaths.Root,"orange-bridge-fixture-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\",\"-Xmx12345m\",\"-Dother=true\"]}");File.WriteAllText(e.Mods,"mods\n{\nmod = ZombieBuddy,\nmod = Viewpoint,\nmod = ShootToThrillMultiplayer,\n}\n");File.WriteAllText(Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(e.Game,"zbNative.dll"),"fixture");var store=new PresentationBridge();string cfg=File.ReadAllText(e.Config);File.WriteAllText(Path.Combine(e.Game,PresentationBridge.Name),"unmanaged");bool rejected=false;try{store.Enable(e,source);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Config)==cfg,"unknown owned-name bridge is never overwritten");File.Delete(Path.Combine(e.Game,PresentationBridge.Name));using(var locked=new FileStream(e.Config,FileMode.Open,FileAccess.Read,FileShare.Read)){rejected=false;try{store.Enable(e,source);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Config)==cfg&&!File.Exists(Path.Combine(e.Game,PresentationBridge.Name)),"locked launch config rolls back newly staged bridge files");}string journal=(string)typeof(PresentationBridge).GetMethod("Journal",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(store,new object[]{e});Directory.CreateDirectory(journal);rejected=false;try{store.Enable(e,source);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Config)==cfg&&!File.Exists(Path.Combine(e.Game,PresentationBridge.Name)),"journal write failure rolls back committed argument and staged files");Directory.Delete(journal);store.Enable(e,source);Check(store.Enabled(e)&&File.ReadAllText(e.Config).Contains("-Xmx12345m"),"bridge enable journals files and preserves existing memory arguments");string managed=File.ReadAllText(e.Config);File.WriteAllText(e.Config,managed.Replace("-javaagent:"+PresentationBridge.Name,"-javaagent:"+Path.Combine(e.Game,PresentationBridge.Name).Replace('\\','/')));rejected=false;try{store.Disable(e);}catch{rejected=true;}Check(rejected&&File.Exists(Path.Combine(e.Game,PresentationBridge.Name)),"changed absolute agent argument refuses file cleanup instead of breaking launch");File.WriteAllText(e.Config,managed);using(var locked=new FileStream(journal,FileMode.Open,FileAccess.Read,FileShare.Read)){rejected=false;try{store.Disable(e);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Config)==managed&&File.Exists(Path.Combine(e.Game,PresentationBridge.Name)),"locked journal refuses disable before removing active files");}File.WriteAllText(Path.Combine(e.Game,PresentationBridge.ConfigName),"manual-edit=true");store.Disable(e);Check(File.ReadAllText(Path.Combine(store.LastBackup,PresentationBridge.ConfigName))=="manual-edit=true","modified bridge settings retained in disable backup");Check(!store.Enabled(e)&&!File.Exists(Path.Combine(e.Game,PresentationBridge.Name))&&File.ReadAllText(e.Config).Contains("-Dother=true")&&File.ReadAllText(e.Mods).Contains(ShootClient.Id),"bridge disable preserves other arguments and shooting configuration");}
 }
}
